/**
 * Expo config plugin: Gradle build tuning.
 *
 * `apps/trainer-mobile/android` is git-ignored and regenerated by
 * `expo prebuild`, so hand-edits to `android/gradle.properties` are lost on the
 * next prebuild and never reach a teammate or CI. This plugin is the durable
 * home for those settings: prebuild re-applies them every time.
 *
 * Only build-infrastructure knobs belong here. Anything that changes what the
 * app *is* (SDK levels, permissions, packaging) belongs in `app.json`.
 */

const { withGradleProperties } = require('expo/config-plugins');

/**
 * Properties applied to `android/gradle.properties` on every prebuild.
 *
 * Rationale for each value:
 *
 * - `org.gradle.jvmargs`
 *     The Expo template ships 2 GB of heap and 512 MB of metaspace. A New
 *     Architecture build runs codegen, Kotlin 2.x and AGP resource merging in
 *     one daemon and reliably exceeds that, surfacing as an opaque
 *     `OutOfMemoryError` or a daemon that disappears mid-build. `-Xmx` is a
 *     ceiling rather than a reservation, so raising it costs nothing on smaller
 *     machines. `-Dfile.encoding=UTF-8` pins the JVM's default charset: on
 *     Windows it would otherwise be the system ANSI code page, which corrupts
 *     non-ASCII strings in resources and makes builds differ from CI.
 *
 * - `org.gradle.caching`
 *     Reuses task outputs across builds and across branch switches. The Expo
 *     CLI already passes `--build-cache` for `expo run:android`; setting it
 *     here extends the same behaviour to bare `./gradlew` runs and to CI.
 *
 * - `org.gradle.configureondemand`
 *     Configures only the projects the invoked task actually needs. Matches the
 *     `--configure-on-demand` flag the Expo CLI passes, so a direct Gradle
 *     invocation does not silently do more work than `expo run:android`.
 *
 * - `kotlin.daemon.jvmargs`
 *     Left unset, the Kotlin compile daemon sizes its heap from total system
 *     RAM and then competes with the Gradle daemon, Metro and the editor.
 *     Capping it keeps a 16 GB developer machine responsive during a build.
 *
 * @type {ReadonlyArray<{ key: string, value: string, comment: string }>}
 */
const TUNING = [
  {
    key: 'org.gradle.jvmargs',
    value:
      '-Xmx4096m -XX:MaxMetaspaceSize=1024m -XX:+HeapDumpOnOutOfMemoryError -Dfile.encoding=UTF-8',
    comment:
      'Headroom for codegen + Kotlin + AGP in one daemon; UTF-8 keeps Windows builds identical to CI.',
  },
  {
    key: 'org.gradle.caching',
    value: 'true',
    comment: 'Reuse task outputs across builds and branches.',
  },
  {
    key: 'org.gradle.configureondemand',
    value: 'true',
    comment: 'Configure only the projects the invoked task needs.',
  },
  {
    key: 'kotlin.daemon.jvmargs',
    value: '-Xmx2048m -XX:MaxMetaspaceSize=512m',
    comment: 'Stop the Kotlin daemon from sizing itself off total system RAM.',
  },
];

/**
 * Sets `key` to `value`, replacing an existing entry in place so the plugin is
 * idempotent across repeated prebuilds and so template ordering is preserved.
 *
 * @param {import('expo/config-plugins').AndroidConfig.Properties.PropertiesItem[]} properties
 * @param {{ key: string, value: string, comment: string }} entry
 */
function upsertProperty(properties, { key, value, comment }) {
  const index = properties.findIndex((item) => item.type === 'property' && item.key === key);

  if (index !== -1) {
    properties[index] = { type: 'property', key, value };
    return properties;
  }

  properties.push({ type: 'empty' });
  properties.push({ type: 'comment', value: comment });
  properties.push({ type: 'property', key, value });
  return properties;
}

/** @type {import('expo/config-plugins').ConfigPlugin} */
const withGradleTuning = (config) =>
  withGradleProperties(config, (modConfig) => {
    modConfig.modResults = TUNING.reduce(upsertProperty, modConfig.modResults);
    return modConfig;
  });

module.exports = withGradleTuning;
